"""Small CPU tensor helpers used by RetinaPy's local checks."""

__version__ = "2.4.1"


class Tensor(list):
    def mean(self):
        return sum(self) / len(self) if self else 0.0


def tensor(values):
    return Tensor(float(v) for v in values)


def manual_seed(seed):
    return int(seed)

